() => {
  const cards = Array.from(document.querySelectorAll('li.s-card, li.s-item'));
  const out = [];
  for (const c of cards) {
    const t = c.querySelector('.s-card__title, .s-item__title');
    const p = c.querySelector('.s-card__price, .s-item__price');
    const cap = c.querySelector('.s-card__caption, .s-item__caption, .s-item__title--tagblock');
    if (!t || !p) continue;
    out.push({title: t.innerText.trim(), price: p.innerText.trim(), cap: cap ? cap.innerText.trim() : ''});
  }
  return {count: out.length, rows: out.slice(0, 40), title: document.title};
}

() => {
  const links = Array.from(document.querySelectorAll('a[href*="/marketplace/item/"]'));
  const out = [];
  const seen = new Set();
  for (const a of links) {
    const txt = a.innerText.trim();
    if (!txt) continue;
    const m = txt.match(/A?U?\$[\d,]+/);
    if (!m) continue;
    const price = parseInt(m[0].replace(/[^\d]/g,''),10);
    const key = txt.slice(0,60);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({price, txt: txt.replace(/\n/g,' | ').slice(0,120)});
  }
  return {count: out.length, rows: out.slice(0,25)};
}

