() => {
  const inputs = Array.from(document.querySelectorAll('input'));
  const loc = inputs.find(i => (i.getAttribute('aria-label')||'').toLowerCase().includes('location'));
  if (!loc) return 'no-loc';
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  setter.call(loc, '');
  loc.dispatchEvent(new Event('input', {bubbles: true}));
  loc.focus();
  return loc.value;
}

() => {
  const inputs = Array.from(document.querySelectorAll('input'));
  const loc = inputs.find(i => (i.getAttribute('aria-label')||'').toLowerCase().includes('location'));
  const next = Array.from(document.querySelectorAll('[role=button],button')).find(b => (b.innerText||'').trim()==='Next');
  return {location: loc ? loc.value : null, nextDisabled: next ? next.getAttribute('aria-disabled') : 'no-next'};
}

async () => {
  const start = Date.now();
  let href = location.href;
  while (Date.now() - start < 14000) {
    href = location.href;
    if (/\/marketplace\/item\/\d+/.test(href)) return {outcome: 'url_match', href};
    if (/\/marketplace\/you\/selling/.test(href) || /\/marketplace\/your_listings/.test(href)) return {outcome: 'your_listings_redirect', href};
    await new Promise(r => setTimeout(r, 500));
  }
  return {outcome: 'timeout', href};
}

() => {
  const f = document.querySelector('iframe[src*="ads/ad_preview_generator_iframe"]');
  if (!f || !f.src) return null;
  const m = f.src.match(/[?&]creative_spec=([^&]+)/);
  if (!m) return null;
  try {
    const spec = JSON.parse(decodeURIComponent(m[1]));
    const ld = spec.object_story_spec.link_data;
    if (!ld || typeof ld.link !== 'string' || typeof ld.name !== 'string') return null;
    return { url: ld.link, name: ld.name };
  } catch (e) {
    return null;
  }
}

